/**
 * Service icon keys. A key names a brand logo in the dashboard (web/src/components/brandIcons.ts,
 * generated by web/scripts/gen-brand-icons.mjs) or one of the placeholders below.
 */
import type { Service } from './types.ts';

/** Icon key for a Docker image (matched against the brand logo set in the dashboard). Apps come before the generic runtimes they are built on. */
export function iconForImage(image: string): string | null {
  const img = image.toLowerCase().split('@')[0];
  const rules: [RegExp, string][] = [
    // Self-hosted apps
    [/nextcloud/, 'nextcloud'],
    [/n8n/, 'flow'],
    [/uptime-kuma/, 'pulse'],
    [/ollama/, 'spark'],
    [/open-?webui/, 'spark'],
    [/teamspeak/, 'teamspeak'],
    [/minecraft|itzg\/mc-/, 'minecraft'],
    [/nocodb/, 'nocodb'],
    [/vaultwarden/, 'vaultwarden'],
    [/bitwarden/, 'bitwarden'],
    [/jellyfin/, 'jellyfin'],
    [/plexinc|(^|\/)plex(-media-server)?(:|$)/, 'plex'],
    [/emby/, 'emby'],
    [/immich/, 'immich'],
    [/home-?assistant/, 'homeassistant'],
    [/node-?red/, 'nodered'],
    [/mosquitto/, 'mosquitto'],
    [/zigbee2mqtt/, 'zigbee2mqtt'],
    [/frigate/, 'frigate'],
    [/portainer/, 'portainer'],
    [/nginx-proxy-manager/, 'npm'],
    [/pi-?hole/, 'pihole'],
    [/adguard/, 'adguard'],
    [/wireguard|wg-easy/, 'wireguard'],
    [/tailscale/, 'tailscale'],
    [/syncthing/, 'syncthing'],
    [/paperless/, 'paperless'],
    [/wordpress/, 'wordpress'],
    [/ghost/, 'ghost'],
    [/mattermost/, 'mattermost'],
    [/rocket\.?chat/, 'rocketchat'],
    [/matrix|synapse|dendrite|conduit/, 'matrix'],
    [/mastodon/, 'mastodon'],
    [/onlyoffice/, 'onlyoffice'],
    [/collabora/, 'collabora'],
    [/bookstack/, 'bookstack'],
    [/outline/, 'outline'],
    [/hedgedoc/, 'hedgedoc'],
    [/excalidraw/, 'excalidraw'],
    [/searxng/, 'searxng'],
    [/freshrss/, 'freshrss'],
    [/audiobookshelf/, 'audiobookshelf'],
    [/calibre/, 'calibre'],
    [/sonarr/, 'sonarr'],
    [/radarr/, 'radarr'],
    [/qbittorrent/, 'qbittorrent'],
    [/transmission/, 'transmission'],
    [/mealie/, 'mealie'],
    [/grocy/, 'grocy'],
    [/actualbudget|actual-server/, 'actualbudget'],
    [/firefly/, 'firefly'],
    [/umami/, 'umami'],
    [/plausible/, 'plausible'],
    [/matomo/, 'matomo'],
    [/metabase/, 'metabase'],
    [/directus/, 'directus'],
    [/strapi/, 'strapi'],
    [/pocketbase/, 'pocketbase'],
    [/appwrite/, 'appwrite'],
    [/authentik/, 'authentik'],
    [/authelia/, 'authelia'],
    [/keycloak/, 'keycloak'],
    [/sentry/, 'sentry'],
    [/netdata/, 'netdata'],
    [/ntfy/, 'ntfy'],
    [/jenkins/, 'jenkins'],
    [/drone/, 'drone'],
    [/code-server/, 'codeserver'],
    [/phpmyadmin/, 'phpmyadmin'],
    [/adminer/, 'table'],
    [/grafana/, 'grafana'],
    [/prometheus/, 'prometheus'],
    [/influxdb/, 'influxdb'],
    [/(^|\/)vault(:|$)/, 'vault'],
    [/gitea|forgejo/, 'gitea'],
    [/gitlab/, 'gitlab'],
    // Data stores and infrastructure
    [/postgres|postgis|timescale|pgvector|supabase\/postgres/, 'postgres'],
    [/mariadb/, 'mariadb'],
    [/mysql|percona/, 'mysql'],
    [/mongo/, 'mongo'],
    [/redis|valkey|keydb|dragonfly/, 'redis'],
    [/minio/, 'bucket'],
    [/neo4j/, 'neo4j'],
    [/cassandra/, 'cassandra'],
    [/qdrant/, 'qdrant'],
    [/rabbitmq/, 'rabbitmq'],
    [/elasticsearch|opensearch/, 'elasticsearch'],
    [/kibana/, 'kibana'],
    [/kafka|redpanda/, 'kafka'],
    [/meilisearch/, 'meilisearch'],
    [/clickhouse/, 'clickhouse'],
    [/traefik/, 'wave'],
    [/haproxy/, 'haproxy'],
    [/nginx/, 'nginx'],
    [/caddy/, 'caddy'],
    [/(^|\/)(httpd|apache)(:|$)/, 'apache'],
    [/tomcat/, 'tomcat'],
    [/curl/, 'curl'],
    // Runtimes and base systems
    [/oven\/bun|(^|\/)bun(:|$)/, 'bun'],
    [/deno/, 'deno'],
    [/(^|\/)node(:|$)/, 'node'],
    [/(^|\/)python(:|$)/, 'python'],
    [/golang|(^|\/)go(:|$)/, 'go'],
    [/(^|\/)rust(:|$)/, 'rust'],
    [/(^|\/)ruby(:|$)/, 'ruby'],
    [/(^|\/)php(:|$)/, 'php'],
    [/(^|\/)(eclipse-temurin|openjdk|amazoncorretto)(:|$)/, 'java'],
    [/dotnet/, 'dotnet'],
    [/(^|\/)elixir(:|$)/, 'elixir'],
    [/(^|\/)alpine(:|$)/, 'alpine'],
    [/(^|\/)ubuntu(:|$)/, 'ubuntu'],
    [/(^|\/)debian(:|$)/, 'debian'],
  ];
  for (const [re, key] of rules) if (re.test(img)) return key;
  return null;
}

/** Icon key for a zero-config build ("node (pnpm, next.js)", "python", …). */
export function iconForStack(stack: string | null | undefined): string | null {
  const s = (stack ?? '').toLowerCase();
  if (s.includes('next.js')) return 'next';
  if (s.startsWith('node')) return 'node';
  if (s.startsWith('static site')) return 'vite';
  if (s.startsWith('static')) return 'static';
  for (const k of ['python', 'go', 'rust', 'deno', 'php', 'ruby']) if (s.startsWith(k)) return k;
  return null;
}

/** Icons Servify picks when it knows nothing better. Anything else (a logo, a key someone chose) is left alone. */
const PLACEHOLDERS = new Set(['box', 'folder', 'git', 'cron']);
/** Base systems and tools say little about what a service does; a scheduled job reads better as a clock. */
const GENERIC = new Set(['alpine', 'ubuntu', 'debian', 'curl']);

/**
 * A better automatic icon for a service, or null to keep the one it has. Uses its image, or for a build the
 * base image the running build started from; scheduled jobs without an app logo get the clock ('cron').
 */
export function betterIcon(svc: Pick<Service, 'icon' | 'source' | 'schedule'>, baseRef?: string | null): string | null {
  const cur = svc.icon;
  if (!PLACEHOLDERS.has(cur) && !GENERIC.has(cur)) return null;
  const ref = svc.source.type === 'image' ? svc.source.image : baseRef;
  const fromImage = ref ? iconForImage(ref) : null;
  let next: string | null;
  if (svc.schedule) next = fromImage && !GENERIC.has(fromImage) ? fromImage : 'cron';
  else if (fromImage) next = fromImage;
  else next = cur === 'cron' ? (svc.source.type === 'local' || svc.source.type === 'upload' ? 'folder' : svc.source.type === 'git' ? 'git' : 'box') : null;
  return next && next !== cur ? next : null;
}
